    if (ff != 0x0000 && ff != 0x4000) return 0;
    // ipv4 checksum
    if (!ip_csum_ok(ip)) return 0;
    const uint8_t *udp = ip + 20;
    uint32_t udplen = (udp[4]<<8)|udp[5];
    if (udplen != iplen - 20) return 0;
    if (udplen < 8+12+4) return 0;
    if (((udp[0]<<8)|udp[1]) != 4791) return 0;
    if (((udp[2]<<8)|udp[3]) != 4791) return 0;
    if (udp[6] || udp[7]) return 0;               // udp checksum zero
    const uint8_t *bth = udp + 8;
    uint8_t op = bth[0];
    if (op != 0x04 && op != 0x11) return 0;
    if (bth[1] != 0) return 0;
    if (bth[2] != 0xff || bth[3] != 0xff) return 0;
    uint32_t qpn = ((uint32_t)bth[4]<<24)|((uint32_t)bth[5]<<16)|((uint32_t)bth[6]<<8)|bth[7];
    if (qpn & 0xff000000u) return 0;              // QPN top byte zero
    uint32_t apsn = be32(bth+8);
    uint8_t top = apsn >> 24;
    if (op == 0x04 ? (top != 0x80) : (top != 0x00)) return 0;
    uint32_t bodylen = udplen - 8 - 12 - 4;
    if (op == 0x04) { out->is_ack=0; out->plen = bodylen; out->payload = bth+12; }
