```python
def prog_encode(case):
    out = bytearray()
    pack = struct.pack_into  # or use out += struct.pack
    for ev in case['events']:
        op = ev['op']
        if op == 'data':
            out += b'\x01'
            out += struct.pack('<BIIiI', ev['rank'], ev['p'], ev.get('count',1), ev.get('step',1), ev.get('seed',0))
            vals = ev.get('values')
            if vals is None:
                out += struct.pack('<I', 0)
            else:
                out += struct.pack('<I', len(vals))
                out += struct.pack('<%dI' % len(vals), *vals)
            xors = ev.get('xor', [])
            out += struct.pack('<I', len(xors))
            for off, val in xors:
                out += struct.pack('<IB', off, val)
        elif op == 'ack':
            out += b'\x02' + struct.pack('<BI', ev['rank'], ev['upto'])
        elif op == 'wire':
            raw = bytes.fromhex(ev['hex'])
            out += b'\x03' + struct.pack('<BI', ev['rank'], len(raw)) + raw
        elif op == 'budget':
            out += b'\x04' + struct.pack('<q', ev['n'])
        elif op == 'flush':
            out += b'\x05'
        elif op == 'retry':
            out += b'\x06' + struct.pack('<B', ev['rank'])
        elif op == 'snap':
            tag = ev['tag'].encode('utf-8')
            out += b'\x07' + struct.pack('<H', len(tag)) + tag
        elif op == 'train':
            r = ev['ranks']
            out += b'\x08' + struct.pack('<IIIBBBBBI', ev['p'], ev['count'], ev['width'], r[0], r[1], r[2], r[3], 1 if ev.get('reverse',False) else 0, ev.get('seed',0))
        else:
            raise ValueError
    return bytes(out)
```

Careful with struct.pack('<IIIBBBBBI', ...) alignment: struct.pack with '<' has no alignment ✓ so the format is exactly 4+4+4+1+1+1+1+1+4 = 21 bytes ✓.

